<section class="container"><div class="p-5 rounded-4 hero mb-4"><h1>Multi-vendor marketplace</h1><p>Browse curated products from approved independent vendors.</p><form class="row g-2"><div class="col-md-6"><input name="q" class="form-control" placeholder="Search products"></div><div class="col-md-3"><select name="category" class="form-select"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?=e($c['slug'])?>"><?=e($c['name'])?></option><?php endforeach ?></select></div><div class="col-md-3"><button class="btn btn-dark w-100">Search</button></div></form></div><div class="row g-4"><?php foreach($products as $p): ?><div class="col-6 col-lg-3"><div class="card h-100"><img class="card-img-top product-img" src="/uploads/<?=e($p['image']?:'placeholder.webp')?>"><div class="card-body"><h2 class="h6"><a href="/product/<?=e($p['slug'])?>"><?=e($p['name'])?></a></h2><p class="small text-muted"><?=e($p['store_name'])?></p><strong>$<?=e($p['sale_price'] ?: $p['price'])?></strong></div></div></div><?php endforeach ?></div></section>
